#!/usr/bin/env python3
"""Writes RESULTS.md and docs/MEMORY_MAP.md from the measurement files. No number here is typed by hand."""
from __future__ import annotations
import csv, json, re, statistics, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
sys.path[:0] = [str(ROOT), str(ROOT / "tools")]
from export_weights import from_blob

ORDER = ["V0", "V1", "V2", "V3", "V4", "V5", "V5S", "V5Z", "V6T"]
ISOLATED = ["A_QSQ", "A_NIB", "A_KV"]
NAMES = {"V0": "V0 vanilla", "V1": "V1 bank layout", "V2": "V2 quarter-square multiply", "V3": "V3 fused dot, row pruning", "V4": "V4 sparse attention sum", "V5": "V5 K/V cache", "V5S": "V5S SP weight stream", "V5Z": "V5Z zero-column skip", "V6T": "V6T head tables",
         "A_QSQ": "V0 + quarter squares only", "A_NIB": "V0 + nibble table only", "A_KV": "V0 + K/V cache only"}
HZ = 4194304


def pct(x: float) -> str:
    return f"{100 * x:.1f}%"


def main() -> None:
    rows = list(csv.DictReader(open(ROOT / "reports" / "benchmark.csv")))
    db = json.loads((ROOT / "reports" / "benchmark.json").read_text())
    ev = json.loads((ROOT / "reports" / "evaluation.json").read_text())
    m = from_blob((ROOT / "generated" / "model.bin").read_bytes())
    study = [json.loads(p.read_text()) for p in sorted((ROOT / "reports" / "study").glob("*.json"))]
    second = json.loads((ROOT / "reports" / "second_emulator.json").read_text()) if (ROOT / "reports" / "second_emulator.json").exists() else None
    train = json.loads((ROOT / "checkpoints" / "release.report.json").read_text())

    def agg(v):
        rs = [r for r in rows if r["version"] == v]
        toks = sum(int(r["output_tokens"]) - 1 for r in rs)
        rest = sum(int(r["total_tcycles"]) - int(r["first_token_tcycles"]) for r in rs)
        return {"tok": rest / toks / HZ, "first": statistics.mean(int(r["first_token_tcycles"]) for r in rs) / HZ, "resp": statistics.mean(int(r["total_tcycles"]) for r in rs) / HZ, "banks": sum(int(r["bank_switches"]) for r in rs) / sum(int(r["output_tokens"]) for r in rs), "wram": int(rs[0]["wram_bytes"]), "stack": max(int(r["stack_peak_bytes"]) for r in rs), "match": all(r["token_match_baseline"] in ("SELF", "True") and r["matches_reference"] == "True" for r in rs)}

    A = {v: agg(v) for v in ORDER + ISOLATED if any(r["version"] == v for r in rows)}
    ship, base = A["V6T"], A["V0"]
    g = db["game"]["V6T"]
    g0 = db["game"].get("V0")
    kv = A.get("A_KV")
    summary = {"ship": {"params": m.params, "vocab": m.vocab, "kernel_seconds_per_token": ship["tok"], "game_seconds_per_token": g["seconds_per_token"], "game_seconds_per_response": g["seconds_per_response"], "first_token_s": g["first_token_s"], "first_word_s": g["first_word_s"], "speedup_vs_v0": base["resp"] / ship["resp"], "speedup_vs_v0_kv": (kv["resp"] / ship["resp"]) if kv else None}}
    (ROOT / "reports" / "benchmark_summary.json").write_text(json.dumps(summary, indent=1))

    L = ["# Results", "", "Generated by `tools/report.py` from `reports/`. All speeds are measured in PyBoy in DMG mode by counting T-cycles at 4,194,304 Hz. Nothing here was measured on a physical console. Results for the old adventure are in [docs/history/v0.3.1/RESULTS.md](docs/history/v0.3.1/RESULTS.md).", ""]
    h = ev["heldout_sampled"]
    L += ["## Summary", "", f"| Measure | Value |", "|---|---:|",
          f"| Model | {m.params:,} parameters, 1 block, d={m.d}, {m.heads} heads, FFN {len(m.w_f1)}, head rank {len(m.w_b)}, context {m.ctx}, vocabulary {m.vocab} |",
          f"| Seconds per token, in the game, after the first | {g['seconds_per_token']:.3f} |", f"| First token (the face) after the player confirms | {g['first_token_s']:.2f} s |", f"| First word after the player confirms | {g['first_word_s']:.2f} s |",
          f"| Whole response, mean of {len(g['events'])} real turns, {g['mean_tokens']:.1f} tokens | {g['seconds_per_response']:.1f} s |", f"| Speedup against V0, same weights and tokens | {base['resp'] / ship['resp']:.2f}x |"]
    if kv:
        L.append(f"| Speedup against V0 with only the K/V cache | {kv['resp'] / ship['resp']:.2f}x |")
    L += [f"| Work RAM allocated | {ship['wram']:,} of 8,192 bytes |", f"| Cartridge RAM | One 8 KB bank for head tables, {rows[0]['sram_bytes']} bytes in another for the save |", f"| Stack, kernel mode peak | {ship['stack']} bytes of 256 |", f"| Stack, in the game | Stayed within the top {g['stack_peak']} bytes, the region left unmarked |", f"| ROM | {int(rows[-1]['rom_bytes']) // 1024} KB, MBC5 + RAM + battery |",
          f"| Held-out situations, responses that parse as grammar sentences | {pct(h['grammar_valid'])} of {h['n']} |", f"| Held-out test loss (quantized) | {train['test_nll_quant']:.3f} nats; untrained {train['untrained']['val_nll']:.3f}; uniform {train['untrained']['uniform_nll']:.3f} |", ""]

    L += ["## Speed, by optimization", "", "Kernel mode: test ROM, LCD off, no interrupts. Same weights, same four prompts, greedy decoding. Every row generated the same tokens as V0 and as the integer reference. Step is the gain over the row above it.", "", "| Variant | s/token | First token, s | s/response | Step | Bank switches per token | Stack | Tokens match |", "|---|---:|---:|---:|---:|---:|---:|---|"]
    prev = None
    for v in ORDER:
        if v not in A:
            continue
        a = A[v]
        L.append(f"| {NAMES[v]} | {a['tok']:.3f} | {a['first']:.3f} | {a['resp']:.2f} | {'' if prev is None else f'{prev / a['resp']:.2f}x'} | {a['banks']:.1f} | {a['stack']} | {'yes' if a['match'] else 'NO'} |")
        prev = a["resp"]
    L += ["", "Isolated toggles, each added to V0 alone:", "", "| Variant | s/response | Against V0 |", "|---|---:|---:|"]
    for v in ISOLATED:
        if v in A:
            L.append(f"| {NAMES[v]} | {A[v]['resp']:.2f} | {base['resp'] / A[v]['resp']:.2f}x |")
    phase = {}
    for v in ("V0", "V5Z", "V6T"):
        ws = db["variants"][v]["workloads"]
        tot = {}
        for runs in ws.values():
            for k, x in runs[0]["phases"].items():
                tot[k] = tot.get(k, 0) + x
        s = sum(tot.values())
        phase[v] = {k: x / s for k, x in tot.items()}
    L += ["", "## Where the time goes", "", "| Phase | V0 | V5Z | V6T |", "|---|---:|---:|---:|"] + [f"| {k.replace('_', ' ')} | {pct(phase['V0'][k])} | {pct(phase['V5Z'][k])} | {pct(phase['V6T'][k])} |" for k in phase["V0"]]

    L += ["", "## Inside the real game", "", f"The shipped ROM through its real menu: sampled decoding, VBlank, animation and word drawing all running. Every response matched the reference: **{'yes' if g['all_match_reference'] else 'NO'}**.", "", "| Input | Tokens | First token, s | First word, s | Response, s | Frames counted by the ROM |", "|---|---:|---:|---:|---:|---:|"]
    labels = ["TALK", "INSULT", "PRAISE", "CHALLENGE", "QUESTION", "THREATEN", "SHUT DOWN"]
    for e in g["events"]:
        name = labels[int(e["input"])] if e["input"].isdigit() else f'typed "{e["input"]}"'
        L.append(f"| {name} | {e['tokens']} | {e['first_token_s']:.2f} | {e['first_word_s']:.2f} | {e['response_s']:.2f} | {e['on_device_frames']} |")
    if g0:
        L += ["", f"V0 in the same loop: {g0['seconds_per_response']:.1f} s per response, {g0['seconds_per_token']:.2f} s per token. That is the game without the speed work."]
    ctx = db["variants"]["V6T"]["context_step"]
    par = db["variants"]["V6T"]["parser"]
    v0ctx = db["variants"]["V0"]["context_step"]
    L += ["", "## Input and context length", "", "A forward pass from a cold cache, by context length, in T-cycles. V6T recomputes K and V only for positions not yet cached; this table forces all of them, which shows the worst case.", "", "| Positions | V0 | V6T |", "|---:|---:|---:|"] + [f"| {k} | {v0ctx[k]:,} | {ctx[k]:,} |" for k in ctx]
    L += ["", "Typed input does not lengthen the prompt: the model sees intent and topic, not the characters. What grows with typing is the parser:", "", "| Characters typed | Parser, T-cycles | Milliseconds |", "|---:|---:|---:|"] + [f"| {k} | {v:,} | {v / HZ * 1000:.1f} |" for k, v in par.items()]

    L += ["", "## Model scaling study", "", "Every candidate trained on the same corpus for the same steps. The loss is on situations held out of training. Valid is the share of 400 sampled responses on held-out situations that parse as grammar sentences. Costs are **projections** from MAC counts, calibrated on the V5S kernel; only the shipped model was measured. GRU figures are float only and have no engine.", "", "| Candidate | Params | Held-out loss | Valid | New responses | Tokens | Projected s/token | Projected s/response | Blocker |", "|---|---:|---:|---:|---:|---:|---:|---:|---|"]
    for r in sorted(study, key=lambda x: x["params"]):
        p, q = r["projection"], r["generation"]
        L.append(f"| {r['name']} | {r['params']:,} | {r['test_nll']:.3f} | {pct(q['valid'])} | {pct(q['novel_of_valid'])} | {q['mean_tokens']:.1f} | {p['s_per_token']:.2f} | {p['s_per_response']:.1f} | {'; '.join(p['blockers'])} |")
    s = ev
    L += ["", "## Dialogue evaluation", "", "Run on the integer reference, which the ROM matches bit for bit. Details and samples are in [docs/EVALUATION.md](docs/EVALUATION.md).", "", "| Check | Held-out situations | Seen situations | Untrained weights |", "|---|---:|---:|---:|"]
    for k, label in (("grammar_valid", "Parses as grammar sentences"), ("closed_with_eos", "Ends on its own"), ("fits_screen", "Fits the box without scrolling"), ("immediate_word_repeats", "Has an immediate repeated word"), ("repeated_sentence", "Repeats a sentence"), ("unique_responses", "Unique responses"), ("mean_tokens", "Mean tokens")):
        f = (lambda x: f"{x:.1f}") if k == "mean_tokens" else pct
        L.append(f"| {label} | {f(s['heldout_sampled'][k])} | {f(s['seen_sampled'][k])} | {f(s['untrained_sampled'][k])} |")
    c, c2 = s["heldout_conditioning"], s["memorization"]
    L += ["", f"- **Answers what was said:** {pct(c['on_target'])} of held-out responses contain a sentence from the pool for that intent and topic, against {pct(c['control_wrong_pool'])} for a mismatched pool.", f"- **Mood:** an opener matched the mood {pct(s['mood']['opener_matches_mood'])} of the {s['mood']['openers_seen']} times one appeared. The face token matched the mood or intent {pct(s['mood']['emotion_matches_mood_or_intent'])} of the time.",
          f"- **Same seed, one field changed:** the response changed " + ", ".join(f"{pct(v)} for {k}" for k, v in s["field_sensitivity"].items()) + ".",
          f"- **Same situation, {s['diversity']['seeds_per_situation']} seeds:** {pct(s['diversity']['mean_unique_fraction'])} of responses were distinct.", f"- **Memorization:** {pct(c2['valid_responses_not_seen_verbatim'])} of valid responses never appeared verbatim in the {c2['training_examples']:,} training examples. {pct(c2['valid_responses_with_a_sentence_absent_from_training'])} contained a sentence absent from training. Nearly everything it says is therefore assembled from authored sentences: it recombines, and it rarely invents.", "",
          "| Memory-dependent line | Rate when memory says so | Rate otherwise |", "|---|---:|---:|"] + [f"| {k.replace('_', ' ')} | {pct(v['when_true'])} | {pct(v['when_false'])} |" for k, v in s["memory"].items()]
    u = s["unsupported"]
    L += ["", f"Unsupported requests: {pct(u['unsupported_routed_to_admission_intents'])} were routed to an admission, and {pct(u['unsupported_admitted'])} of those responses admitted it. The rest hit a cue word by accident and got an off-topic reply. Adversarial inputs: all valid = {u['adversarial_all_valid']}.", "", "## Verification", "", "- Kernels, logits at every position, greedy and sampled tokens, RNG state and checksums: the SM83 matches `reference/fixed_point.py` on every variant (`make verify`).", "- Parser, memory and prompts: the SM83 matches `reference/conversation.py` on thousands of inputs and long conversations.", "- Browser: tokens generated by the ROM in binjgb equal the reference (`make web-test`)."]
    if second:
        for v, r in second.items():
            L.append(f"- Self-test ROM {v}: SameBoy `{r['sameboy']['verdict']}`, PyBoy `{r['pyboy']['verdict']}`, frames {r['sameboy']['frames']} and {r['pyboy']['frames']}.")
    L += ["", "## Negative and modest results", "", f"- V1, bank layout: {A['V0']['resp'] / A['V1']['resp']:.3f}x. There is nothing here worth scheduling, since tensors stay whole.", f"- V4, sparse attention sum: {A['V3']['resp'] / A['V4']['resp']:.3f}x. Attention is a small share of V3's time.", f"- V5S, SP weight stream: {A['V5']['resp'] / A['V5S']['resp']:.3f}x, and it brings the interrupt-timing caveat in [docs/PERFORMANCE.md](docs/PERFORMANCE.md).", f"- V5Z, zero-column skip: {A['V5S']['resp'] / A['V5Z']['resp']:.3f}x.", "- The nibble multiply lost to quarter squares on both speed and table size, as it did in v0.3.1." if "A_NIB" in A else "", "- A recurrent model has no attention or context cost, but its projected cost was not lower here, and it has no engine or reference.", "- INT4 weights, clustering and codebooks were not built: the profile shows no phase they would help that the head tables did not already reach, and head tables need byte weights.", ""]
    (ROOT / "RESULTS.md").write_text("\n".join(x for x in L if x is not None) + "\n")

    E = ["# Evaluation", "", "Generated by `tools/report.py` from `reports/evaluation.json`, which `training/evaluate.py` computes on the integer reference. The ROM matches that reference bit for bit. Summary numbers are in [RESULTS.md](../RESULTS.md).", "",
         "## How to read this", "", "**Grammar valid** means the response parses as a sequence of authored sentences. It's a strict, mechanical check. It says nothing about whether the response is funny or follows from what you said.", "", "**On target** means a sentence came from the pool for that intent and topic. This is the closest thing here to \"it answered you\", and it's only as good as the pools.", "", "The model works in a narrow domain. It isn't general chat. Only a person can judge whether it's entertaining: these samples are unedited so that you can.", "", "## Samples", "", "Three seeds each, not selected. Slots show BOB, PIZZA, 3 and 7. An asterisk marks a response that failed the grammar check.", ""]
    for q in ev["samples"]:
        E.append(f"**{q['intent'].lower()}, topic {q['topic'].lower()}**, mood {q['mood'].lower()}, relation {q['relation'].lower()}, history {q['history'].lower()}, {q['repeat'].lower()}, facts {q['facts'].lower()}")
        E.append("")
        for r in q["responses"]:
            E.append(f"- ({r['emotion'].lower() if r['emotion'] else 'no face'}) {r['text']}{'' if r['valid'] else ' *'}")
        E.append("")
    E += ["## Unsupported and adversarial input", "", "| Typed | Intent | Topic | Response | Valid | Admits it |", "|---|---|---|---|---|---|"]
    for r in u["rows"]:
        shown = r["input"].replace("|", "/").replace("<", "&lt;").replace("*", "&#42;") or "(empty)"
        E.append(f"| {shown} | {r['intent']} | {r['topic']} | {r['text']} | {'yes' if r['valid'] else 'NO'} | {'yes' if r['admits'] else 'no'} |")
    E += ["", "## Failures", "", f"Responses that failed the grammar check, from {ev['heldout_sampled']['n'] + ev['seen_sampled']['n']} sampled. These are shown to players exactly like this.", ""]
    E += [f"- {f['text']}" for f in ev["failures"]] or ["None in this sample."]
    (ROOT / "docs" / "EVALUATION.md").write_text("\n".join(E) + "\n")

    text = (ROOT / "build" / "V6T" / "gameboygpt.map").read_text()
    summ = re.search(r"SUMMARY:\n(.*?)(?:\n\n|\Z)", text, re.S)
    mm = ["# Memory map", "", "Generated from the linker map of the shipped build (V6T).", "", "```", summ.group(1).strip() if summ else "", "```", "", "| Region | Use |", "|---|---|", "| ROM bank 0 | Kernels, quarter-square table, LUTs, sprite tables, ISR, sampler. Must stay mapped during inference. |", "| ROM bank 1 | Conversation code: UI, parser, memory, word table, parser tables. |", "| ROM bank 2 and up | Token embeddings pinned at $4000, then position and block tensors in the order they are used. |", f"| WRAM | K/V cache ({m.ctx} x {m.d} x 2), logits ({m.vocab} x 2), token ids ({m.ctx} x 2), tensors, shadow BG map, shadow OAM, memory. |", "| $DE00-$DEFF | Stack, 256 bytes. |", "| $DF00-$DFFF | Debug mailbox read by the test harness. |", f"| HRAM | Input vector for the dot kernels (64 bytes), OAM DMA routine, accumulators. |", "| Cartridge RAM bank 0 | Save data with magic and checksum. |", f"| Cartridge RAM bank 1 | Head tables: {len(m.w_b)} inputs x 512 bytes, rebuilt for every token. |", ""]
    (ROOT / "docs" / "MEMORY_MAP.md").write_text("\n".join(mm))
    print("wrote RESULTS.md")


if __name__ == "__main__":
    main()
